CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_chief_examiner_claim` (IN `p_subject_code` VARCHAR(10), IN `p_subject_name` VARCHAR(100), IN `p_paper_no` INT, IN `p_belt_no` INT, IN `p_rate_value` DECIMAL(16,15), IN `p_tax` DECIMAL(3.2), IN `p_session_year` VARCHAR(10), IN `p_session_name` VARCHAR(50), IN `p_marking_centre_code` VARCHAR(100), IN `p_marking_centre_name` VARCHAR(100))   BEGIN
        marking_centre_code,
        marking_centre_name,
        nrc,
        examiner_number,
        tpin,
        full_name,
        address,
        province,
        district,
        position,
        no_of_scripts,
        sortcode,
        account_no,
        net_rate,
        grossed_up_rate,
        gross_pay,
        fifteen_wht,
        net_pay,
        bank,
        branch,
        subject_code,
        subject_name,
        paper_no,
        belt_no,
        session,
        session_name
    )
    WITH highest_claim AS (
        SELECT 
            COUNT(ex.examiner_number) AS no_of_examiners,
            ga.no_of_scripts AS no_of_scripts,
            ga.belt_no AS belt_no,
            ga.no_of_scripts / COUNT(ex.examiner_number) AS scripts_per_examiner,
            CASE 
                WHEN ga.no_of_scripts / COUNT(ex.examiner_number) < 100 
                THEN 100 
                ELSE ga.no_of_scripts / COUNT(ex.examiner_number) 
            END AS no_of_scripts_marked
        FROM group_apportion ga
        INNER JOIN examiner ex 
            ON ga.subject = ex.subject_code
           AND ga.paper = ex.paper_no
           AND ga.belt_no = ex.belt_no
           AND ga.marking_centre = ex.marking_centre
        WHERE ex.attendance = 1
          AND ga.subject = p_subject_code
          AND ga.paper = p_paper_no
          AND ga.marking_centre = p_marking_centre_code
          AND ex.role IN ('EXAMINER','TEAM LEADER')
        GROUP BY ga.no_of_scripts, ga.belt_no
    )
    SELECT 
        p_marking_centre_code AS marking_centre_code,
        p_marking_centre_name AS marking_centre_name,
        ex.nrc,
        ex.examiner_number,
        ex.tpin,
        CONCAT(ex.first_name,' ',ex.last_name) AS full_name,
        ex.address,
        ex.province,
        ex.district,
        ex.role AS position,

        (SELECT scripts_per_examiner FROM highest_claim ORDER BY scripts_per_examiner DESC LIMIT 1) AS no_of_scripts,

        ex.sortcode,
        ex.account_no,

        CASE 
            WHEN ex.role = 'CHIEF EXAMINER' THEN mr.chief_examiner 
            ELSE mr.deputy_c_examiner 
        END AS net_rate,

        CASE 
            WHEN ex.role = 'CHIEF EXAMINER' THEN mr.chief_examiner * p_rate_value 
            ELSE mr.deputy_c_examiner * p_rate_value 
        END AS grossed_up_rate,

        ( (SELECT no_of_scripts_marked FROM highest_claim ORDER BY no_of_scripts_marked DESC LIMIT 1) *
          (CASE WHEN ex.role = 'CHIEF EXAMINER' THEN mr.chief_examiner * p_rate_value ELSE mr.deputy_c_examiner * p_rate_value END)
        ) AS gross_pay,

        ( (SELECT no_of_scripts_marked FROM highest_claim ORDER BY no_of_scripts_marked DESC LIMIT 1) *
          (CASE WHEN ex.role = 'CHIEF EXAMINER' THEN mr.chief_examiner * p_rate_value ELSE mr.deputy_c_examiner * p_rate_value END)
        ) * p_tax AS `fifteen_wht`,

        ( (SELECT no_of_scripts_marked FROM highest_claim ORDER BY no_of_scripts_marked DESC LIMIT 1) *
          (CASE WHEN ex.role = 'CHIEF EXAMINER' THEN mr.chief_examiner * p_rate_value ELSE mr.deputy_c_examiner * p_rate_value END)
        ) - 
        ( (SELECT no_of_scripts_marked FROM highest_claim ORDER BY no_of_scripts_marked DESC LIMIT 1) *
          (CASE WHEN ex.role = 'CHIEF EXAMINER' THEN mr.chief_examiner * p_rate_value ELSE mr.deputy_c_examiner * p_rate_value END) * p_tax
        ) AS net_pay,

        ex.bank,
        ex.branch,
        p_subject_code AS subject_code,
        p_subject_name AS subject_name,
        p_paper_no AS paper_no,
        ex.belt_no,
        p_session_year AS session,
        CONCAT(p_session_year,' ',p_session_name) AS session_name
    FROM examiner ex
    INNER JOIN marking_rates mr 
        ON ex.subject_code = mr.subject_code AND ex.paper_no = mr.paper_no
    RIGHT OUTER JOIN group_apportion ga 
        ON mr.subject_code = ga.subject AND mr.paper_no = ga.paper
    WHERE ex.subject_code = ga.subject
      AND ex.paper_no = ga.paper
      AND ex.marking_centre = ga.marking_centre
      AND ex.attendance = 1
      AND ex.role IN ('DEPUTY CHIEF EXAMINER','CHIEF EXAMINER')
      AND ex.subject_code = p_subject_code
      AND ex.paper_no = p_paper_no
      AND ex.marking_centre = p_marking_centre_code
    GROUP BY ex.nrc,ex.examiner_number,ex.tpin,ex.role,ex.address,ex.district,
             ex.province, ex.first_name,ex.last_name,mr.chief_examiner,
             mr.deputy_c_examiner,ex.belt_no,ex.account_no,ex.bank,ex.branch,ex.sortcode;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_data_entry_claim` (IN `p_examiner_number` VARCHAR(50), IN `p_rate_value` DECIMAL(16,15), IN `p_tax` DECIMAL(16,15), IN `p_marking_centre_code` VARCHAR(100), IN `p_marking_centre_name` VARCHAR(255), IN `p_session_year` VARCHAR(10), IN `p_session_name` VARCHAR(50), IN `p_username` VARCHAR(150))   BEGIN
        marking_centre_code,
        marking_centre_name,
        nrc,
        examiner_number,
        tpin,
        full_name,
        phone_number,
        address,
        province,
        district,
        position,
        no_of_scripts,
        sortcode,
        account_no,
        net_rate,
        grossed_up_rate,
        gross_pay,
        fifteen_wht,
        net_pay,
        bank,
        branch,
        subject_code,
        subject_name,
        paper_no,
        belt_no,
        date_claimed,
        session_name,
        session_year
    )
    SELECT 
        p_marking_centre_code AS marking_centre_code,
        p_marking_centre_name AS marking_centre_name,
        ex.nrc AS nrc,
        ex.examiner_number,
        ex.tpin AS tpin,
        CONCAT(ex.first_name, ' ', ex.last_name) AS full_name,
        ex.phone_number AS phone_number,
        ex.address AS address,
        ex.province AS province,
        ex.district AS district,
        ex.role AS position,
        SUM(m.status <> 'L') AS no_of_scripts,
        ex.sortcode AS sortcode,
        ex.account_no AS account_no,
        mr.data_entry AS net_rate,
        mr.data_entry * p_rate_value AS grossed_up_rate,
        SUM(m.status <> 'L') * (mr.data_entry * p_rate_value) AS gross_pay,
        (SUM(m.status <> 'L') * (mr.data_entry * p_rate_value)) * p_tax AS fifteen_wht,
        (SUM(m.status <> 'L') * (mr.data_entry * p_rate_value)) 
          - (SUM(m.status <> 'L') * (mr.data_entry * p_rate_value) * p_tax) AS net_pay,
        ex.bank AS bank,
        ex.branch AS branch,
        su.subject_code AS subject_code,
        su.subject_name AS subject_name,
        pa.paper_no AS paper_no,
        'D/E' AS belt_no,
        DATE(NOW()) AS date_claimed,
        CONCAT(p_session_year,' ',p_session_name) AS session_name,
        p_session_year AS session_year
    FROM examiner ex 
    INNER JOIN marks m ON ex.marking_centre = m.marking_centre
    INNER JOIN marking_rates mr ON m.subject_code = mr.subject_code
    INNER JOIN subjects su ON mr.subject_code = su.subject_code
    INNER JOIN paper pa ON su.subject_code = pa.subject_code
    WHERE m.paper_no = mr.paper_no
      AND m.subject_code = su.subject_code
      AND m.paper_no = pa.paper_no
      AND m.subject_code = pa.subject_code
      AND m.marking_centre = p_marking_centre_code
      AND ex.examiner_number = LEFT(m.entered_by, LOCATE(' ', m.entered_by) - 1)
      AND m.entered_by = p_username
      AND ex.examiner_number = p_examiner_number
      AND ex.role = 'DATA ENTRY OFFICER'
    GROUP BY ex.examiner_number,ex.first_name, ex.last_name, ex.phone_number, ex.address, 
             ex.province, ex.district, ex.bank, ex.branch, ex.sortcode, 
             ex.tpin, ex.account_no, mr.data_entry, ex.nrc, ex.phone_number, 
             su.subject_code, su.subject_name, pa.paper_no, mr.data_entry;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `insert_examiner_claims` (IN `p_subject_code` VARCHAR(10), IN `p_subject_name` VARCHAR(100), IN `p_paper_no` INT, IN `p_belt_no` INT, IN `p_rate_value` DECIMAL(16,15), IN `p_tax` DECIMAL(3.2), IN `p_session_year` VARCHAR(10), IN `p_session_name` VARCHAR(20), IN `p_marking_centre_code` VARCHAR(100), IN `p_marking_centre_name` VARCHAR(100))   BEGIN

        marking_centre_code,
        marking_centre_name,
        nrc,
        examiner_number,
        tpin,
        full_name,
        address,
        province,
        district,
        position,
        no_of_scripts,
        sortcode,
        account_no,
        net_rate,
        grossed_up_rate,
        gross_pay,
        fifteen_wht,
        net_pay,
        bank,
        branch,
        subject_code,
        subject_name,
        paper_no,
        belt_no,
        session,
        session_name
    )
    WITH examiners_claim AS (
        SELECT 
            ex.subject_code AS subject_code,
            ex.paper_no AS paper_no,
            ex.belt_no AS belt_no,
            ex.marking_centre AS marking_centre,
            COUNT(ex.nrc) AS no_of_examiners,
            ga.no_of_scripts AS no_of_scripts
        FROM examiner ex
        INNER JOIN group_apportion ga
            ON ex.subject_code = ga.subject
            AND ex.paper_no = ga.paper
            AND ex.belt_no = ga.belt_no
            AND ex.marking_centre = ga.marking_centre
        WHERE ex.attendance = 1
          AND ex.role IN ('EXAMINER','TEAM LEADER')
          AND ex.subject_code = p_subject_code
          AND ex.paper_no = p_paper_no
          AND ex.belt_no = p_belt_no
          AND ex.marking_centre = p_marking_centre_code
        GROUP BY ex.subject_code, ex.paper_no, ex.belt_no, ex.marking_centre, ga.no_of_scripts
    )
    SELECT 
        p_marking_centre_code AS marking_centre_code,
        p_marking_centre_name AS marking_centre_name,
        ex.nrc,
        ex.examiner_number,
        ex.tpin,
        CONCAT(ex.first_name,' ',ex.last_name) AS full_name,
        ex.address,
        ex.province,
        ex.district,
        ex.role AS position,
        ec.no_of_scripts AS no_of_scripts,
        ex.sortcode,
        ex.account_no,
        CASE 
            WHEN ex.role='TEAM LEADER' THEN mr.t_leader
            WHEN ex.role='CHECKER' THEN mr.checker
            ELSE mr.examiner
        END AS net_rate,
        CASE 
            WHEN ex.role='TEAM LEADER' THEN mr.t_leader * p_rate_value
            WHEN ex.role='CHECKER' THEN mr.checker * p_rate_value
            ELSE mr.examiner * p_rate_value
        END AS grossed_up_rate,
        (CASE WHEN ec.no_of_scripts < 100 THEN 100 ELSE ec.no_of_scripts END)
        * (CASE 
             WHEN ex.role='TEAM LEADER' THEN mr.t_leader * p_rate_value
             WHEN ex.role='CHECKER' THEN mr.checker * p_rate_value
             ELSE mr.examiner * p_rate_value
           END) / ec.no_of_examiners AS gross_pay,
        (CASE WHEN ec.no_of_scripts < 100 THEN 100 ELSE ec.no_of_scripts END)
        * (CASE 
             WHEN ex.role='TEAM LEADER' THEN mr.t_leader * p_rate_value
             WHEN ex.role='CHECKER' THEN mr.checker * p_rate_value
             ELSE mr.examiner * p_rate_value
           END) / ec.no_of_examiners * p_tax AS `fifteen_wht`,
        ((CASE WHEN ec.no_of_scripts < 100 THEN 100 ELSE ec.no_of_scripts END)
        * (CASE 
             WHEN ex.role='TEAM LEADER' THEN mr.t_leader * p_rate_value
             WHEN ex.role='CHECKER' THEN mr.checker * p_rate_value
             ELSE mr.examiner * p_rate_value
           END) / ec.no_of_examiners)
        - ((CASE WHEN ec.no_of_scripts < 100 THEN 100 ELSE ec.no_of_scripts END)
        * (CASE 
             WHEN ex.role='TEAM LEADER' THEN mr.t_leader * p_rate_value
             WHEN ex.role='CHECKER' THEN mr.checker * p_rate_value
             ELSE mr.examiner * p_rate_value
           END) / ec.no_of_examiners * p_tax) AS net_pay,
        ex.bank,
        ex.branch,
        p_subject_code,
        p_subject_name,
        p_paper_no,
        ex.belt_no,
        p_session_year,
        CONCAT(p_session_year,' ',p_session_name) AS session_name
    FROM examiner ex
    INNER JOIN examiners_claim ec
        ON ex.subject_code = ec.subject_code
        AND ex.paper_no = ec.paper_no
        AND ex.belt_no = ec.belt_no
        AND ex.marking_centre = ec.marking_centre
    INNER JOIN marking_rates mr
        ON ex.subject_code = mr.subject_code
        AND ex.paper_no = mr.paper_no
    WHERE ex.attendance = 1
      AND ex.role IN ('EXAMINER','TEAM LEADER','CHECKER')
      AND ex.subject_code = p_subject_code
      AND ex.paper_no = p_paper_no
      AND ex.belt_no = p_belt_no
      AND ex.marking_centre = p_marking_centre_code;

END$$

DELIMITER ;

